INSERT INTO public.topics (id, proposition, category, context, sources, topic_date, is_featured) VALUES (21, 'Should the United States adopt a universal healthcare system?', 'Politics', 'The US spends roughly $4.5 trillion on health care, about 17 percent of GDP, far more than peer nations, while tens of millions remain underinsured. Systems like the UK''s NHS and Canadian Medicare offer contrasting models.', '[{"title": "CMS: National Health Expenditure Data", "url": "https://www.cms.gov/data-research/statistics-trends-and-reports/national-health-expenditure-data"}, {"title": "KFF: health costs and the uninsured", "url": "https://www.kff.org/uninsured/"}, {"title": "Commonwealth Fund: international comparisons", "url": "https://www.commonwealthfund.org"}]'::jsonb, '2026-09-24', true) ON CONFLICT (id) DO UPDATE SET proposition=EXCLUDED.proposition, category=EXCLUDED.category, context=EXCLUDED.context, sources=EXCLUDED.sources, topic_date=EXCLUDED.topic_date, is_featured=EXCLUDED.is_featured;
INSERT INTO public.topics (id, proposition, category, context, sources, topic_date, is_featured) VALUES (22, 'Should tipping be abolished in favor of higher base wages for service workers?', 'Business', 'The federal tipped minimum wage has been $2.13 an hour since 1991. Ballot fights in DC and Chicago and California''s full-wage model have made the tip credit a national flashpoint.', '[{"title": "DOL: tipped employees under the FLSA", "url": "https://www.dol.gov/agencies/whd/fact-sheet/15-tipped-employees-under-the-flsa"}, {"title": "Ballotpedia: DC Initiative 82 (2022)", "url": "https://ballotpedia.org/Washington,_D.C.,_Initiative_82,_Tip_Credit_Elimination_Initiative_(2022)"}, {"title": "Bureau of Labor Statistics", "url": "https://www.bls.gov"}]'::jsonb, '2026-09-24', false) ON CONFLICT (id) DO UPDATE SET proposition=EXCLUDED.proposition, category=EXCLUDED.category, context=EXCLUDED.context, sources=EXCLUDED.sources, topic_date=EXCLUDED.topic_date, is_featured=EXCLUDED.is_featured;
INSERT INTO public.topics (id, proposition, category, context, sources, topic_date, is_featured) VALUES (23, 'Should AI-generated films be eligible for major awards like the Oscars?', 'Entertainment', 'In 2025, the Academy ruled that generative AI use neither helps nor harms a film''s Oscar eligibility. The decision followed the 2023 actors'' and writers'' strikes, where AI was a central dispute, and the rise of tools like OpenAI''s Sora and Runway.', '[{"title": "Academy of Motion Picture Arts and Sciences", "url": "https://www.oscars.org/news"}, {"title": "SAG-AFTRA", "url": "https://www.sagaftra.org/"}, {"title": "AP: Entertainment News", "url": "https://apnews.com/hub/entertainment"}]'::jsonb, '2026-09-24', false) ON CONFLICT (id) DO UPDATE SET proposition=EXCLUDED.proposition, category=EXCLUDED.category, context=EXCLUDED.context, sources=EXCLUDED.sources, topic_date=EXCLUDED.topic_date, is_featured=EXCLUDED.is_featured;
INSERT INTO public.topics (id, proposition, category, context, sources, topic_date, is_featured) VALUES (24, 'Should smartphones be banned in K-12 schools nationwide?', 'Lifestyle', 'Florida banned phones during class time in 2023, and UNESCO called the same year for a global ban on smartphones in schools. Research links phone presence to lower test scores and weaker student well-being.', '[{"title": "UNESCO: Global Education Monitoring Report", "url": "https://www.unesco.org/gem-report/en"}, {"title": "Common Sense Media: Research", "url": "https://www.commonsensemedia.org/research"}, {"title": "Pew Research Center", "url": "https://www.pewresearch.org/internet/"}]'::jsonb, '2026-09-24', false) ON CONFLICT (id) DO UPDATE SET proposition=EXCLUDED.proposition, category=EXCLUDED.category, context=EXCLUDED.context, sources=EXCLUDED.sources, topic_date=EXCLUDED.topic_date, is_featured=EXCLUDED.is_featured;
INSERT INTO public.topics (id, proposition, category, context, sources, topic_date, is_featured) VALUES (25, 'Should sports betting advertisements be banned from live game broadcasts?', 'Sports', 'Americans legally wagered roughly $120 billion on sports in 2023, and betting ads now saturate game broadcasts. The UK answered similar concerns with a ''whistle-to-whistle'' ban on gambling ads during live sport, while US problem-gambling helplines report rising demand.', '[{"title": "American Gaming Association: Commercial Gaming Revenue Data", "url": "https://www.americangaming.org/"}, {"title": "Betting and Gaming Council: Whistle-to-Whistle Ban", "url": "https://bettingandgamingcouncil.com/"}, {"title": "NCPG National Problem Gambling Helpline", "url": "https://www.ncpgambling.org/help-treatment/national-helpline/"}]'::jsonb, '2026-09-24', false) ON CONFLICT (id) DO UPDATE SET proposition=EXCLUDED.proposition, category=EXCLUDED.category, context=EXCLUDED.context, sources=EXCLUDED.sources, topic_date=EXCLUDED.topic_date, is_featured=EXCLUDED.is_featured;
INSERT INTO public.topics (id, proposition, category, context, sources, topic_date, is_featured) VALUES (26, 'Should the standard full-time workweek be cut to four days with no pay cut?', 'Business', 'The UK''s 2022-23 trial across 61 companies found revenue steady and burnout down on a four-day week with no pay cut, echoing Iceland''s large-scale public-sector trials and Microsoft Japan''s 2019 experiment. Advocates call it the next labor standard; skeptics call it a perk for office workers.', '[{"title": "4 Day Week Global: UK Trial Results", "url": "https://www.4dayweek.com/"}, {"title": "Autonomy: Iceland Shorter Working Week Trials", "url": "https://autonomy.work/"}, {"title": "Reuters: Four-Day Week Coverage", "url": "https://www.reuters.com/"}]'::jsonb, '2026-09-23', false) ON CONFLICT (id) DO UPDATE SET proposition=EXCLUDED.proposition, category=EXCLUDED.category, context=EXCLUDED.context, sources=EXCLUDED.sources, topic_date=EXCLUDED.topic_date, is_featured=EXCLUDED.is_featured;
INSERT INTO public.topics (id, proposition, category, context, sources, topic_date, is_featured) VALUES (27, 'Should the federal government break up Big Tech companies?', 'Politics', 'The Justice Department''s antitrust cases against Google have revived calls to break up Big Tech, echoing the 2020 House Judiciary report that found Amazon, Apple, Google, and Meta hold monopoly power in digital markets.', '[{"title": "DOJ Antitrust Division", "url": "https://www.justice.gov/antitrust"}, {"title": "House Judiciary Committee", "url": "https://judiciary.house.gov"}, {"title": "Reuters technology coverage", "url": "https://www.reuters.com/technology/"}, {"title": "Pew Research Center: Internet and Technology", "url": "https://www.pewresearch.org/internet/"}]'::jsonb, '2026-09-23', false) ON CONFLICT (id) DO UPDATE SET proposition=EXCLUDED.proposition, category=EXCLUDED.category, context=EXCLUDED.context, sources=EXCLUDED.sources, topic_date=EXCLUDED.topic_date, is_featured=EXCLUDED.is_featured;
INSERT INTO public.topics (id, proposition, category, context, sources, topic_date, is_featured) VALUES (28, 'Should college athletes be classified as employees with salaries and benefits?', 'Sports', 'The roughly $2.8 billion House v. NCAA settlement and the Dartmouth men''s basketball union vote have forced the question of whether college athletes are employees entitled to salaries and benefits.', '[{"title": "NCAA.org", "url": "https://www.ncaa.org/"}, {"title": "Associated Press", "url": "https://apnews.com/"}, {"title": "National Labor Relations Board", "url": "https://www.nlrb.gov/"}, {"title": "U.S. Bureau of Labor Statistics", "url": "https://www.bls.gov/"}]'::jsonb, '2026-09-23', false) ON CONFLICT (id) DO UPDATE SET proposition=EXCLUDED.proposition, category=EXCLUDED.category, context=EXCLUDED.context, sources=EXCLUDED.sources, topic_date=EXCLUDED.topic_date, is_featured=EXCLUDED.is_featured;
INSERT INTO public.topics (id, proposition, category, context, sources, topic_date, is_featured) VALUES (29, 'Should daylight saving time be abolished permanently?', 'Lifestyle', 'The Senate''s Sunshine Protection Act would end clock changes, but sleep researchers argue for permanent standard time instead, pointing to spikes in heart attacks and crashes after the spring shift.', '[{"title": "American Academy of Sleep Medicine", "url": "https://aasm.org/"}, {"title": "Reuters", "url": "https://www.reuters.com/"}, {"title": "Associated Press", "url": "https://apnews.com/"}]'::jsonb, '2026-09-23', false) ON CONFLICT (id) DO UPDATE SET proposition=EXCLUDED.proposition, category=EXCLUDED.category, context=EXCLUDED.context, sources=EXCLUDED.sources, topic_date=EXCLUDED.topic_date, is_featured=EXCLUDED.is_featured;
